// _pointer_sizeLoose returns the length of the encoding of the Loose that m
// points at.
func _pointer_sizeLoose(m *Loose) int {
	n := 0
	if m.Note != "" {
		n += 1 + wire.SizeBytes(len(m.Note))
	}
	if m.Size != 0 {
		n += 1 + wire.SizeUvarint(uint64(m.Size))
	}
	return n
}

// _pointer_sizeSliceInt32 returns the length of the encoding of the elements of
// x, a []int32.
func _pointer_sizeSliceInt32(x []int32) int {
	n := 0
	for k := range x {
		n += wire.SizeUvarint(wire.Zigzag(int64(x[k])))
	}
	return n
}

// _pointer_putSliceInt32 writes the encoding of x, a []int32, into the end of
// buf, which has room for it, and returns its length.
func _pointer_putSliceInt32(buf []byte, x []int32) int {
	i := len(buf)
	for k := len(x) - 1; k >= 0; k-- {
		i = wire.PutUvarint(buf, i, wire.Zigzag(int64(x[k])))
	}
	i = wire.PutUvarint(buf, i, uint64(len(buf)-i))
	return len(buf) - i
}

// _pointer_putLoose writes the encoding of the Loose that m points at into the
// end of buf, which has room for it, and returns its length.
func _pointer_putLoose(buf []byte, m *Loose) int {
	i := len(buf)
	if m.Size != 0 {
		i = wire.PutUvarint(buf, i, uint64(m.Size))
		i = wire.PutTag(buf, i, 2<<3|wire.Varint)
	}
	if m.Note != "" {
		i = wire.PutRaw(buf, i, m.Note)
		i = wire.PutUvarint(buf, i, uint64(len(m.Note)))
		i = wire.PutTag(buf, i, 1<<3|wire.Bytes)
	}
	return len(buf) - i
}

// _pointer_readLoose sets the Loose that m points at to the value encoded in
// data and reuses its memory, as DecodeKanon does. data starts at offset off of
// slab, and the decode enters depth levels below the value at most.
func _pointer_readLoose(m *Loose, data []byte, slab string, off, depth int) error {
	m.Note = ""
	m.Size = 0
	return _pointer_mergeLoose(m, data, slab, off, depth)
}

// _pointer_readSliceInt32 appends the elements that data encodes, a []int32
// without its length, to *dst. data starts at offset off of slab, and the
// decode enters depth levels below the value at most. loc and num locate the
// field in errors.
func _pointer_readSliceInt32(dst *[]int32, data []byte, slab string, off, depth int, loc string, num int) error {
	if depth < 0 {
		return wire.DepthError(loc, num, off)
	}
	x := *dst
	if x == nil && len(data) > 0 {
		x = make([]int32, 0, wire.CountVarints(data))
	}
	for i := 0; i < len(data); {
		x = append(x, 0)
		last := len(x) - 1
		u, n := wire.Uvarint(data[i:])
		if n <= 0 {
			return wire.ReadError(n, loc, num, off+i)
		}
		s := wire.Unzigzag(u)
		if s != int64(int32(s)) {
			return wire.RangeError(s, "int32", loc, num, off+i)
		}
		x[last] = int32(s)
		i += n
	}
	*dst = x
	return nil
}

// _pointer_cloneLoose copies the Loose that src points at into the one that dst
// points at, as CloneKanon does.
func _pointer_cloneLoose(dst, src *Loose) {
	dst.Note = strings.Clone(src.Note)
	dst.Size = src.Size
}

// _pointer_mergeLoose merges the encoding in data, which starts at offset off
// of slab, into the Loose that m points at, as MergeKanon does. The decode
// enters depth levels below m at most.
func _pointer_mergeLoose(m *Loose, data []byte, slab string, off, depth int) error {
	for i := 0; i < len(data); {
		at := i
		tag, n := wire.Uvarint(data[i:])
		if n <= 0 {
			return wire.ReadError(n, "Loose", 0, off+i)
		}
		i += n
		switch tag >> 3 {
		case 1:
			if tag != 1<<3|wire.Bytes {
				return wire.FormatError(tag, wire.Bytes, "Loose.Note", off+at)
			}
			l, n := wire.Uvarint(data[i:])
			if n <= 0 || uint64(len(data)-i-n) < l {
				return wire.ReadError(n, "Loose.Note", 1, off+i)
			}
			i += n
			m.Note = slab[off+i : off+i+int(l)]
			i += int(l)
		case 2:
			if tag != 2<<3|wire.Varint {
				return wire.FormatError(tag, wire.Varint, "Loose.Size", off+at)
			}
			u, n := wire.Uvarint(data[i:])
			if n <= 0 {
				return wire.ReadError(n, "Loose.Size", 2, off+i)
			}
			if u != uint64(uint16(u)) {
				return wire.RangeError(u, "uint16", "Loose.Size", 2, off+i)
			}
			m.Size = uint16(u)
			i += n
		default:
			n, err := wire.Skip(data[i:], tag, "Loose", 0, off+at)
			if err != nil {
				return err
			}
			i += n
		}
	}
	return nil
}
